export const analyticsMarkup="<section id=\"profileAnalytics\" class=\"view\"><section class=\"dashboard-chart white-card\"><div class=\"chart-heading\"><div><h2>Solving rhythm</h2><p>First accepted solves, grouped by date.</p></div><div class=\"chart-filters\"><select id=\"graphMode\" aria-label=\"Chart frequency\"><option value=\"daily\">Daily</option><option value=\"monthly\">Monthly</option><option value=\"yearly\">Yearly</option></select><select id=\"graphMeasure\" aria-label=\"Chart measurement\"><option value=\"period\">Period solves</option><option value=\"cumulative\">Cumulative solves</option></select><label class=\"graph-forecast-toggle\" title=\"Projection based on recent solves, not a guarantee\"><input id=\"graphForecast\" type=\"checkbox\" checked aria-describedby=\"graphForecastNote\"> Show forecast</label><select id=\"graphForecastHorizon\" aria-label=\"Forecast horizon\"><option value=\"7\">7 days</option><option value=\"14\">14 days</option><option value=\"30\">30 days</option></select><input id=\"graphMonth\" type=\"month\" aria-label=\"Chart month\"><input id=\"graphYear\" type=\"number\" min=\"2000\" max=\"2200\" aria-label=\"Chart year\" hidden><select id=\"graphTopic\" aria-label=\"Chart topic\"><option value=\"\">All topics</option></select></div></div><div id=\"graphLegend\" class=\"graph-legend\"></div><div class=\"graph-scroll\"><svg id=\"frequencyChart\" viewBox=\"0 0 900 225\" role=\"img\" aria-label=\"Problem solving frequency comparison\"></svg></div><p id=\"graphForecastNote\" class=\"graph-forecast-note\" role=\"note\" hidden></p><div class=\"comparison-controls\"><span>Compare with friends</span><select id=\"compareOne\" aria-label=\"First friend\"><option value=\"\">Choose a friend</option></select><select id=\"compareTwo\" aria-label=\"Second friend\"><option value=\"\">Choose a friend</option></select></div><p id=\"dashboardMessage\" class=\"muted\" role=\"status\"></p><p class=\"chart-footnote\">First accepted solves only · UTC dates · Solid = actual, dotted = statistical estimate. Non-ML forecasts use historical backtesting; future solving is never guaranteed.</p></section><section class=\"white-card topic-summary\"><div><h2>Patterns growing</h2><p>Unique problems solved out of the currently published catalog.</p></div><div id=\"topicBreakdown\" aria-label=\"Progress by topic\"></div></section></section>  ";
